<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import * as THREE from 'three';
  import { audioStore } from '$stores/audio.svelte';
  import AudioPlayer from '$components/audio/AudioPlayer.svelte';
  let canvas: HTMLCanvasElement;
  let renderer: THREE.WebGLRenderer | null = null;
  let frame = 0;
  let bars: THREE.Mesh[] = [];
  let selectedId = $state<string | null>(null);
  let error = $state('');
  let renameId = $state<string | null>(null);
  let renameValue = $state('');

  onMount(() => { audioStore.loadRecordings(); createVisualizer(); });
  onDestroy(() => { if (typeof window !== 'undefined') cancelAnimationFrame(frame); renderer?.dispose(); if (audioStore.isRecording) audioStore.cancelRecording(); });
  async function record() { error = ''; try { await audioStore.startRecording(); } catch (err) { error = err instanceof Error ? err.message : 'We could not access your microphone.'; } }
  function saveName() { if (renameId && renameValue.trim()) audioStore.renameRecording(renameId, renameValue.trim()); renameId = null; }
  function beginRename(id: string, name: string) { renameId = id; renameValue = name; }
  function format(seconds: number) { const m = Math.floor(seconds / 60); return `${m}:${Math.floor(seconds % 60).toString().padStart(2, '0')}`; }
  function createVisualizer() {
    const scene = new THREE.Scene(); const camera = new THREE.PerspectiveCamera(58, 1, .1, 100); camera.position.set(0, 2.5, 8); camera.lookAt(0, 0, 0);
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true }); renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    const group = new THREE.Group(); scene.add(group); const geometry = new THREE.BoxGeometry(.17, 1, .17);
    for (let index = 0; index < 36; index++) { const hue = .53 + index / 400; const material = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(hue, .86, .62), emissive: new THREE.Color().setHSL(hue, .86, .12), metalness: .65, roughness: .25 }); const bar = new THREE.Mesh(geometry, material); const angle = index / 36 * Math.PI * 2; bar.position.set(Math.cos(angle) * 2.15, 0, Math.sin(angle) * 2.15); bar.userData = { angle, seed: index * .66 }; group.add(bar); bars.push(bar); }
    scene.add(new THREE.AmbientLight(0x6b7cff, 1.3)); const key = new THREE.PointLight(0x22d3ee, 18, 20); key.position.set(0, 4, 3); scene.add(key); const core = new THREE.Mesh(new THREE.IcosahedronGeometry(.65, 2), new THREE.MeshStandardMaterial({ color: 0xddd6fe, emissive: 0x4f46e5, emissiveIntensity: .55, metalness: .75, roughness:.2 })); scene.add(core);
    const resize = () => { if (!renderer) return; const { clientWidth:w, clientHeight:h } = canvas; renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix(); }; window.addEventListener('resize', resize); resize();
    const draw = () => { const t = performance.now() / 1000; const intensity = audioStore.isRecording && !audioStore.isPaused ? 1 : .22; group.rotation.y += .005; core.rotation.x += .008; core.rotation.y += .006; bars.forEach((bar) => { const wave = .6 + (Math.sin(t * (audioStore.isRecording ? 7 : 1.5) + bar.userData.seed) + 1) * intensity; bar.scale.y = wave; bar.position.y = (wave - 1) / 2; }); renderer?.render(scene, camera); frame = requestAnimationFrame(draw); }; draw();
  }
</script>

<svelte:head><title>Audio Studio · Happy Study 3D</title><meta name="description" content="Record, replay, and organise spoken study notes." /></svelte:head>

<div class="studio">
  <section class="hero"><canvas bind:this={canvas}></canvas><div class="hero-copy"><p class="eyebrow">AUDIO STUDY STUDIO</p><h1>Say it.<br /><em>Remember it.</em></h1><p>Record a short explanation after every topic. Teaching the idea in your own words is one of the strongest ways to make it stick.</p></div></section>
  <section class="recorder"><div class="meter"><span class:live={audioStore.isRecording && !audioStore.isPaused}></span><div><p>{audioStore.isRecording ? (audioStore.isPaused ? 'PAUSED' : 'RECORDING') : 'READY TO RECORD'}</p><strong>{format(audioStore.recordingTime)}</strong></div></div><div class="controls">{#if !audioStore.isRecording}<button class="record" onclick={record}>● Start recording</button>{:else}<button onclick={() => audioStore.pauseRecording()}>{audioStore.isPaused ? 'Resume' : 'Pause'}</button><button class="stop" onclick={() => audioStore.stopRecording()}>Save recording</button><button class="quiet" onclick={() => audioStore.cancelRecording()}>Discard</button>{/if}</div></section>
  {#if error}<p class="error">{error} Check your browser permissions and try again.</p>{/if}
  <section class="tips"><div><b>01</b><p><strong>Keep it short.</strong> Record one concept in 60–90 seconds.</p></div><div><b>02</b><p><strong>Use a simple script.</strong> Definition → example → common mistake.</p></div><div><b>03</b><p><strong>Replay before an exam.</strong> Your own voice makes revision feel familiar.</p></div></section>
  <section class="library"><div class="library-heading"><div><p class="eyebrow">YOUR RECORDING LIBRARY</p><h2>{audioStore.recordings.length} study note{audioStore.recordings.length === 1 ? '' : 's'}</h2></div><span>Stored privately on this device</span></div>{#if audioStore.isLoading}<p class="empty">Loading your recordings…</p>{:else if !audioStore.recordings.length}<p class="empty">Your audio notes will appear here after your first recording.</p>{:else}<div class="recordings">{#each audioStore.recordings as recording, i}<article class:selected={selectedId === recording.id}><button class="row" onclick={() => selectedId = selectedId === recording.id ? null : recording.id}><span class="number">{String(i + 1).padStart(2,'0')}</span><span class="recording-copy"><strong>{recording.name}</strong><small>{format(recording.duration)} · {new Date(recording.timestamp).toLocaleDateString()}</small></span><span class="chevron">{selectedId === recording.id ? '−' : '+'}</span></button>{#if selectedId === recording.id}<div class="expanded">{#if renameId === recording.id}<form onsubmit={(event) => { event.preventDefault(); saveName(); }}><input bind:value={renameValue} aria-label="Recording name" /><button>Save</button><button type="button" onclick={() => renameId = null}>Cancel</button></form>{:else}<div class="actions"><button onclick={() => beginRename(recording.id, recording.name)}>Rename</button><button class="delete" onclick={() => audioStore.deleteRecording(recording.id)}>Delete</button></div>{/if}<AudioPlayer src={recording.url} title={recording.name} /></div>{/if}</article>{/each}</div>{/if}</section>
</div>

<style>
  .studio{display:grid;gap:1.2rem}.hero{min-height:390px;position:relative;overflow:hidden;border-radius:30px;background:radial-gradient(circle at 65% 42%,#1e3a8a,#111827 57%);border:1px solid rgba(34,211,238,.28)}.hero canvas{position:absolute;inset:0;width:100%;height:100%;opacity:.92}.hero-copy{position:relative;z-index:1;padding:clamp(2rem,6vw,5rem);max-width:620px;background:linear-gradient(90deg,rgba(2,6,23,.88),rgba(2,6,23,.46),transparent)}.eyebrow{font-size:.7rem;letter-spacing:.14em;font-weight:800;color:#67e8f9;margin:0 0 .7rem}.hero h1{font-size:clamp(3.2rem,7vw,5.8rem);line-height:.87;letter-spacing:-.07em;margin:0}.hero em{font-family:Georgia,serif;font-weight:400;color:#67e8f9}.hero p:not(.eyebrow){color:#cbd5e1;line-height:1.7;font-size:1.06rem;margin-top:1.4rem}.recorder,.library{padding:clamp(1.2rem,4vw,2.2rem);border-radius:22px;border:1px solid rgba(148,163,184,.18);background:linear-gradient(145deg,rgba(30,41,59,.85),rgba(15,23,42,.94))}.recorder{display:flex;justify-content:space-between;align-items:center;gap:1rem}.meter{display:flex;gap:1rem;align-items:center}.meter>span{width:13px;aspect-ratio:1;border-radius:50%;background:#64748b}.meter>span.live{background:#f43f5e;box-shadow:0 0 0 8px rgba(244,63,94,.17);animation:pulse 1s infinite}.meter p{font-size:.7rem;letter-spacing:.12em;font-weight:800;color:#94a3b8;margin:0}.meter strong{font:2.4rem ui-monospace,SFMono-Regular,monospace}.controls{display:flex;gap:.6rem;flex-wrap:wrap}.controls button,.actions button,form button{border:1px solid rgba(148,163,184,.26);border-radius:999px;padding:.7rem 1rem;background:#111827;color:#e2e8f0;font-weight:750;cursor:pointer}.controls .record{background:#f43f5e;border-color:#f43f5e;color:#fff}.controls .stop{background:#22c55e;border-color:#22c55e;color:#052e16}.controls .quiet{color:#94a3b8}.error{color:#fecdd3;background:rgba(190,24,93,.15);border:1px solid rgba(244,63,94,.35);padding:1rem;border-radius:12px}.tips{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.tips div{display:flex;gap:.8rem;padding:1.15rem;border-radius:16px;background:rgba(30,41,59,.55);border:1px solid rgba(148,163,184,.14)}.tips b{color:#67e8f9;font-family:Georgia,serif;font-size:1.3rem}.tips p{margin:0;color:#cbd5e1;line-height:1.5;font-size:.88rem}.tips strong{color:#fff}.library-heading{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin-bottom:1.1rem}.library-heading h2{margin:0;font-size:1.8rem}.library-heading>span{font-size:.78rem;color:#94a3b8}.empty{color:#94a3b8;padding:2.4rem 0;text-align:center}.recordings{display:grid;gap:.6rem}.recordings article{border-radius:14px;background:#0b1222;border:1px solid rgba(148,163,184,.15);overflow:hidden}.recordings article.selected{border-color:#22d3ee}.row{width:100%;display:flex;align-items:center;gap:1rem;padding:1rem;background:transparent;border:0;color:#fff;text-align:left;cursor:pointer}.number{font-family:Georgia,serif;color:#67e8f9}.recording-copy{display:grid;gap:.2rem;flex:1}.recording-copy small{color:#94a3b8}.chevron{font-size:1.3rem;color:#67e8f9}.expanded{padding:0 1rem 1rem;border-top:1px solid rgba(148,163,184,.14)}.actions{display:flex;gap:.5rem;justify-content:flex-end;padding:.75rem 0}.actions .delete{color:#fda4af;border-color:#fb7185}.expanded form{display:flex;gap:.5rem;padding:.8rem 0}.expanded input{flex:1;min-width:0;border:1px solid #334155;background:#111827;color:#fff;border-radius:10px;padding:.65rem}@keyframes pulse{50%{transform:scale(.85);opacity:.6}}@media(max-width:700px){.hero{min-height:430px}.hero-copy{padding-top:11rem}.recorder{align-items:flex-start;flex-direction:column}.tips{grid-template-columns:1fr}.library-heading{align-items:flex-start;flex-direction:column}}
</style>
